994	
995	    const auto & nested_column = col_map->getNestedColumn();
996	    const auto & keys_data = col_map->getNestedData().getColumn(0);
997	    const auto & values_data = col_map->getNestedData().getColumn(1);
998	    const auto & offsets = nested_column.getOffsets();
999	
1000	    /// At first step calculate indices in array of values for requested keys.
1001	    auto indices_column = DataTypeNumber<UInt64>().createColumn();
1002	    indices_column->reserve(input_rows_count);
1003	    auto & indices_data = assert_cast<ColumnVector<UInt64> &>(*indices_column).getData();
1004	
1005	    bool executed = false;
1006	    if (!isColumnConst(*arguments[1].column))
1007	    {
1008	        executed = matchKeyToIndexNumber(keys_data, offsets, !!col_const_map, *arguments[1].column, indices_data)
