1014	        executed = matchKeyToIndexNumberConst(keys_data, offsets, index, indices_data)
1015	            || matchKeyToIndexStringConst(keys_data, offsets, index, indices_data);
1016	    }
1017	
1018	    if (!executed)
1019	        throw Exception(ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
1020	            "Illegal types of arguments: {}, {} for function {}",
1021	            arguments[0].type->getName(), arguments[1].type->getName(), getName());
1022	
1023	    ColumnPtr values_array = ColumnArray::create(values_data.getPtr(), nested_column.getOffsetsPtr());
1024	    if (col_const_map)
1025	        values_array = ColumnConst::create(values_array, input_rows_count);
1026	
1027	    /// Prepare arguments to call arrayElement for array with values and calculated indices at previous step.
1028	    ColumnsWithTypeAndName new_arguments =
